import numpy as np
DESCRIPTION=("A one-layer ReLU RNN over the 5 inputs: h_t=relu(x_t*a+h_(t-1)@b) (t=1..5), decision=argmax(h5@c). "
 "State units are rescaled (one scale per unit: |W_x| of that unit) so the input weights a become pure signs "
 "[1,-1,1,-1,1,-1,-1,1] and x is fed as +-x_t; b is the recurrence in those units, c the readout. Scores are "
 "written centred (each unit's five scores sum to 0) so class 5 = -sum of the other four, which leaves every "
 "decision unchanged. Weights 7 decimals.")
a=np.array([1,-1,1,-1,1,-1,-1,1])
b=np.array([.1254034,.0155058,.7225764,.0059288,10.9919613,.0046988,11.2131533,-.0149899,-4.6436625,-.2363669,4.1291816,.4814724,24.0829785,-.9569952,50.3467872,-.0247941,.0131555,-.0085101,-.1068966,-.0122530,-5.8083484,-.0365252,1.8779511,.0049356,5.4022187,-.3071144,-5.6321271,-.8474928,40.7174360,.7622508,24.1272272,.0574557,-.0124503,-.0022767,.0229930,-.0017270,-.7468407,-.0017574,-1.0063394,.0024496,6.7359608,.4594159,1.4583017,.2599200,13.8617565,.0695809,-68.1394921,.0165569,.0106714,.0081019,-.0110450,.0080047,.6547871,.0074819,.7866836,-.0068802,-18.0420579,-.0187999,23.4567911,1.1585586,24.1932989,1.1612508,142.6292313,-.8278961]).reshape(8,8)
c=np.array([.5837401,-.6067912,.5603986,-1.1284196,2.9803578,-3.7782552,-24.2532682,25.7676372,.4785518,.0899148,-1.3149769,.3590877,3.4063938,-14.9067767,32.6193170,-17.7360666,-.0221821,.0933836,-.0250875,-.0251102,-4.1064611,20.8084520,-6.4627437,-6.2636264,-.0456541,-.0494876,.0292550,.0379734,3.0264969,3.5693120,3.9924914,3.8394510]).reshape(8,4)
def model(x,iv):
    s=np.zeros((len(x),8))
    for t in range(5):s=iv('h%d'%(t+1),np.maximum(x[:,t:t+1]*a+s@b,0))
    p=s@c
    return np.column_stack([p,-p.sum(1)])
ALIGN={'h1':['h1'],'h2':['h2'],'h3':['h3'],'h4':['h4'],'h5':['h5']}
